// ❌ OLD: Running 300ms of synchronous processing directly inside the click event
// listener blocks the browser from presenting visual feedback, resulting in a failing INP score (>200ms).
button.addEventListener('click', () => {
  button.classList.add('loading'); // Queued but cannot paint!

  // Synchronous heavy work monopolizes the main thread:
  const results = runHeavyDataCalculations(); 
  renderResults(results);
});

// ✅ NEW: Give immediate visual feedback, yield to let the browser paint the
// button state, then process heavy computation in a separate task slice.
button.addEventListener('click', async () => {
  button.classList.add('loading'); // Immediate visual update

  // Yield execution back to the browser event loop to paint the frame:
  if ('scheduler' in window && 'yield' in scheduler) {
    await scheduler.yield();
  } else {
    await new Promise((resolve) => setTimeout(resolve, 0));
  }

  const results = runHeavyDataCalculations();
  renderResults(results);
});
